<script lang="ts">
  import { tick } from 'svelte';
  import { indexGuideline, loadGuideline, markReady, readHash, writeHash, type Guideline, type HashState, type Rule } from '../../shared/data.js';
  let g = $state.raw<Guideline | null>(null);
  let state = $state.raw<HashState>(readHash());
  let rec = $state(3);
  let search = $state('');
  let failure = $state('');
  const ix = $derived(g ? indexGuideline(g) : null);
  const question = $derived(state.view === 'trace' ? g?.questions.find(q => q.id === state.question) : null);
  const focused = $derived(state.view === 'rule' ? ix?.sentence(`${state.document}:${state.sentence}`) : null);
  const rows = $derived.by(() => {
    if (!g) return [];
    if (state.view === 'rule') return g.rules.filter(r => r.document === state.document && r.sentence === state.sentence);
    if (state.view === 'trace') return (question?.statements ?? []).flatMap(s => g.rules.filter(r => r.document === s.document && r.sentence === s.sentence));
    if (state.view === 'explore') return g.rules.filter(r => r.original.toLowerCase().includes(state.query.toLowerCase()));
    return g.rules.filter(r => ix?.docs.get(r.document)?.rec === rec);
  });
  const matches = $derived(state.view === 'explore' ? g?.documents.flatMap(d => d.sentences.filter(s => s.ace.toLowerCase().includes(state.query.toLowerCase())).map(s => ({d,s}))) ?? [] : []);
  function go(next: HashState) { state = next; writeHash(next); }
  function rule(r: Rule) { go({view:'rule',document:r.document,sentence:r.sentence}); }
  function relation(r: Rule, negative: boolean) { return r.mode === 'fact' ? (negative ? 'does not' : 'fact relation') : `${r.mode}${negative ? ' not' : ''} do`; }
  $effect(() => {
    const changed = () => { state = readHash(); if (state.view === 'explore') search = state.query; };
    addEventListener('hashchange',changed);
    loadGuideline().then(data => g = data).catch(e => failure = String(e));
    return () => removeEventListener('hashchange',changed);
  });
  $effect(() => { if (!g) return; void state; void rec; tick().then(markReady); });
</script>

<main>
  <header><div class="brand">CNL / CKC <span>Graph study 08</span></div><nav aria-label="Views"><button class:active={state.view==='overview'} onclick={() => go({view:'overview'})}>Guideline</button><button class:active={state.view==='trace'} onclick={() => go({view:'trace',question:g?.questions[0]?.id ?? ''})}>Trace an answer</button><button class:active={state.view==='explore'} onclick={() => go({view:'explore',query:'naloxone'})}>Explore</button></nav></header>
  <section class="intro"><h1>Clinical relationships</h1><p>Who acts, under which conditions, and where the recommendation comes from.</p></section>
  {#if failure}<p role="alert">{failure}</p>{:else if !g || !ix}<p>Loading the guideline…</p>{:else}
    <p class="disclaimer">Prototype: {g.derivation} This view does not run Prolog.</p>
    <div class="schema"><strong>Read the graph</strong><span>Nodes name actors, conditions, actions and recommendations. Labelled arrows name their relationships. Each lane keeps one rule’s scope.</span></div>
    {#if state.view === 'overview'}
      <section class="inventory"><h2>The guideline in {g.recommendations.length} recommendations</h2><p>{g.rules.length} clinical rules. Choose a recommendation to inspect its relationships.</p><div class="recs">{#each g.recommendations as r}<button class:selected={rec===r.number} onclick={() => rec=r.number}><b>{r.number}</b><span>{g.rules.filter(rule => rule.document===r.id).length} rules</span></button>{/each}</div><h2>Recommendation {rec}</h2><details><summary>Read the recommendation’s source text</summary><p class="sourceintro">{g.recommendations.find(r => r.number===rec)?.source}</p></details></section>
    {:else if state.view === 'trace'}
      <label class="choose">Choose a question<select value={question?.id ?? ''} onchange={e => go({view:'trace',question:e.currentTarget.value})}>{#each g.questions as q}<option value={q.id}>{q.question}</option>{/each}</select></label>
      {#if !question}<h2>Question not found</h2>{:else}<h2>{question.question}</h2><p>Follow the ordered statements to their rules and sources.</p><ol class="statements">{#each question.statements as s}{@const d=ix.docs.get(s.document)}<li><a href={`#rule=${s.document}:${s.sentence}`} onclick={() => go({view:'rule',...s})}>{ix.sentence(`${s.document}:${s.sentence}`)?.ace}</a><small>{s.document}, sentence {s.sentence} <a href={`${g.pdf}#page=${d?.page}`} target="_blank" rel="noreferrer">Guideline page {d?.page}</a></small><details><summary>Source passage</summary><p>{d?.source}</p></details></li>{/each}</ol>{/if}
    {:else if state.view === 'explore'}
      <form onsubmit={e => {e.preventDefault(); go({view:'explore',query:search});}}><label for="search">Find a clinical term</label><div class="search"><input id="search" bind:value={search} placeholder="Try naloxone"/><button>Find relationships</button></div></form><h2>Relationships mentioning “{state.query}”</h2><p>{rows.length} clinical rules; {matches.length} matching sentences across the knowledge base.</p>
    {:else}
      <h2>{state.document}, sentence {state.sentence}</h2>
      {#if !focused}<p>Sentence not found. Choose Guideline to return to the recommendations.</p>{:else}<p class="original">{focused.ace}</p>{#if rows.length===0}<p>Text reading only: this sentence has no clinical-layer parse.</p><dl class="reading"><dt>Condition</dt><dd>{focused.condition ?? 'No condition in the text split'}</dd><dt>Conclusion</dt><dd>{focused.conclusion}</dd><dt>Modality</dt><dd>{focused.modal}{focused.negated ? ', negated' : ''}</dd></dl>{/if}{/if}
    {/if}
    {#if rows.length>0}<section class="graph" aria-label="Clinical relationship graph"><div class="graphhead"><h2>{state.view==='rule' ? 'One rule, isolated' : 'Rule relationships'}</h2><span>{rows.length} rule lanes</span></div>{#each rows as r}{@const d=ix.docs.get(r.document)}<article class="lane"><div class="lanehead"><button onclick={() => rule(r)}>{r.document.replace('cdc2022-opioid-','')} / sentence {r.sentence}</button><a href={`${g.pdf}#page=${d?.page}`} target="_blank" rel="noreferrer">Page {d?.page}</a></div><div class="triples"><div class="actor node"><small>Actor</small><button onclick={() => go({view:'explore',query:r.subject})}>{r.subject}</button></div>{#if r.condition}<div class="conditionbranch"><div class="connector">requires <span>→</span></div><div class="condition node"><small>Condition</small>{r.condition}</div></div>{:else}<div class="conditionbranch unconditional">No condition in this rule</div>{/if}<div class="actions">{#each r.actions as a}<div class="actionrow"><div class="connector">{relation(r,a.polarity==='negative')} <span>→</span></div><div class="action node"><small>Action</small><button onclick={() => go({view:'explore',query:a.object})}>{a.verb} {a.object}</button>{#each a.modifiers as m}<span class="modifier">{m.preposition} {m.value}</span>{/each}</div></div>{/each}</div><div class="evidence"><div class="connector">stated by <span>→</span></div><button class="recommendation node" onclick={() => rule(r)}><small>Recommendation</small>{d?.rec ?? r.document}</button></div></div><details><summary>Read the source sentence and passage</summary><p>{r.original}</p><p>{d?.source}</p></details></article>{/each}</section>{/if}
    {#if state.view==='rule' && focused}{@const d=ix.docs.get(state.document)}<section class="passage"><h2>Guideline source</h2><p>{d?.source}</p><a href={`${g.pdf}#page=${d?.page}`} target="_blank" rel="noreferrer">Open guideline page {d?.page}</a></section>{/if}
    {#if state.view==='explore'}<section><h2>Sentence index</h2>{#each matches as {d,s}}<details class="result"><summary>{d.id}, sentence {s.n}</summary><p>{s.ace}</p><a href={`#rule=${d.id}:${s.n}`}>Explain this sentence</a> <a href={`${g.pdf}#page=${d.page}`} target="_blank" rel="noreferrer">Page {d.page}</a></details>{/each}{#if matches.length===0}<p>No matching sentences. Search for another clinical term.</p>{/if}</section>{/if}
    <section class="guards"><details><summary>Scope exclusions ({g.exclusions.length} source records)</summary><p>The recommendations do not apply under these conditions. Absence of an exclusion does not establish that a patient is in scope.</p>{#each g.exclusions as e}<p>{e.ace} <a href={`#rule=${e.document}:${e.sentence}`}>{e.document}, sentence {e.sentence}</a></p>{/each}</details><details><summary>Superseded statements ({g.supersessions.length})</summary>{#each g.supersessions as s}<article><p><s>{s.ace}</s></p><p>Superseded {String(s.date).slice(0,4)}-{String(s.date).slice(4,6)}-{String(s.date).slice(6,8)} by <a href={s.url}>{s.citation}</a></p><a href={`#rule=${s.document}:${s.sentence}`}>{s.document}, sentence {s.sentence}</a></article>{/each}</details></section>
    <footer>CDC Clinical Practice Guideline for Prescribing Opioids for Pain, 2022. Material is free on the CDC website. CDC does not endorse this demo.</footer>
  {/if}
</main>

<style>
