0px}.lanehead button{border:0;background:none;padding:0;color:var(--action);text-decoration:underline}.triples{display:grid;grid-template-columns:140px 1fr 1.4fr 135px;gap:18px;align-items:center}.node{padding:15px;border:2px solid var(--border);font-size:17px;line-height:1.35;overflow-wrap:anywhere;background:var(--surface)}.node small{display:block;font-size:12px;color:var(--text-muted);margin-bottom:7px}.node button{padding:0;border:0;background:none;text-align:left;font-size:inherit}.actor{border-radius:50%;min-height:124px;display:flex;justify-content:center;flex-direction:column;text-align:center}.actor button{text-align:center}.condition{border-color:var(--graph-entity);border-radius:2px}.action{border-color:var(--action);border-radius:6px}.recommendation{border-color:var(--graph-document);width:100%;text-align:center;font-size:25px;font-weight:650}.connector{font-size:14px;color:var(--text-muted);display:flex;align-items:center;gap:8px;padding:0 0 6px}.connector span{flex:1;text-align:right;position:relative}.connector span:before{content:'';position:absolute;left:0;right:4px;top:50%;height:1px;background:var(--border)}.actions{display:grid;gap:14px}.modifier{display:block;font-size:14px;color:var(--text-muted);margin-top:5px}.unconditional{color:var(--text-muted);font-size:13px}details{margin-top:14px}summary{cursor:pointer;color:var(--action)}details p{max-width:78ch}.choose{display:block;margin-top:24px}.choose select{display:block;margin-top:6px;padding:10px;max-width:100%;background:var(--surface-raised);color:inherit;border:1px solid var(--border);font:inherit}.statements{padding-left:24px;max-width:90ch}.statements li{padding:12px 0}.statements small{display:block;margin-top:6px}.statements details{font-size:14px;margin-top:4px}a{color:var(--action);overflow-wrap:anywhere}.search{display:flex;gap:12px;margin-top:8px}input{padding:11px;border:1px solid var(--border);background:var(--surface-raised);color:inherit;min-width:0;width:320px}.result{padding:12px;border-bottom:1px solid var(--border)}.guards{margin-top:30px;padding:8px 18px 22px;background:var(--surface-sunken)}.guards article{border-bottom:1px solid var(--border);padding-bottom:12px}footer{margin-top:32px;color:var(--text-muted);font-size:13px;max-width:90ch}.original{font-size:19px}.reading dd{margin:0 0 14px}.reading dt{font-weight:bold}form{margin-top:24px}
  @media(max-width:760px){main{padding:18px}header{align-items:flex-start;flex-direction:column;gap:12px}.brand span{margin-left:12px}nav{flex-wrap:wrap;gap:3px}nav button{padding:8px}h1{font-size:30px}.schema{flex-direction:column;gap:6px}.recs{grid-template-columns:repeat(6,1fr);gap:5px}.triples{grid-template-columns:1fr;gap:12px}.actor{border-radius:24px;min-height:0;text-align:left}.actor button{text-align:left}.lane{padding:16px}.graphhead{padding:0 16px;gap:12px}.graphhead h2{font-size:20px}.graphhead span{font-size:12px}.conditionbranch,.actions,.evidence{margin-left:18px;border-left:2px solid var(--border);padding-left:15px}.lanehead{align-items:flex-start}.lanehead button{font-size:13px}.lanehead a{white-space:nowrap;font-size:13px}.connector{padding-top:4px}.recommendation{text-align:left;font-size:20px}.search{flex-direction:column}.search input{width:100%}.graph{margin-top:20px}.guards{padding:8px 12px 18px}}
</style>
